tasks.solutionCode:
export function formatPooledDbUrl(basePostgresUrl: string): string {
  const url = new URL(basePostgresUrl);
  url.searchParams.set('pgbouncer', 'true');
  url.searchParams.set('connection_limit', '10');
  return url.toString();
}

